/**
 * Generate the catalog apps run.omni.dev can deploy, from the `run` CLI.
 *
 * `run` owns the catalog and the recipe->Fractal-manifest mapping (the SSOT);
 * this calls `run deploy <app> --format json` for each catalog app and writes a
 * committed `src/data/generated/catalogApps.ts`. The committed file is what the
 * site builds against, so a build without the `run` binary on PATH (CI, a
 * contributor without it installed) still ships the last good catalog; re-run
 * with the binary to refresh. Never hand-edit the generated file.
 *
 * Point RUN_BIN at a specific binary (e.g. a local debug build) to regenerate;
 * otherwise `run` is resolved from PATH.
 */

import { resolve } from "node:path";

// The deployable catalog apps. `run` has no machine-readable catalog listing,
// so this mirrors crates/run-core/src/catalog/*.toml; keep it in sync when the
// run catalog gains or drops an app.
const APP_IDS = ["backfeed", "pihole", "runa", "uptime-kuma", "vortex"];

const runBin = process.env.RUN_BIN ?? "run";

const outPath = resolve(
  import.meta.dir,
  "../src/data/generated/catalogApps.ts",
);

interface RunDeployJson {
  name: string;
  displayName?: string | null;
  description?: string | null;
  services: { name: string; image: string; ports: string[] }[];
  inputs: { key: string; label?: string | null; required: boolean }[];
  hasSecrets: boolean;
  hasProxy: boolean;
  fractalManifest: string;
}

/** Run the CLI for one app, or null if it is unavailable or fails. */
const deployJson = (id: string): RunDeployJson | null => {
  let proc: ReturnType<typeof Bun.spawnSync>;

  try {
    proc = Bun.spawnSync([runBin, "deploy", id, "--format", "json"], {
      stdout: "pipe",
      stderr: "pipe",
    });
  } catch (error) {
    // The binary is not on PATH (common in CI); fall back to the committed file
    console.warn(`[catalog] could not run \`${runBin}\`: ${error}`);
    return null;
  }

  if (!proc.success) {
    const stderr = proc.stderr.toString().trim();
    console.warn(
      `[catalog] run deploy ${id} failed: ${stderr || "unknown error"}`,
    );
    return null;
  }

  try {
    return JSON.parse(proc.stdout.toString()) as RunDeployJson;
  } catch (error) {
    console.warn(`[catalog] run deploy ${id} returned invalid JSON: ${error}`);
    return null;
  }
};

const results = APP_IDS.map((id) => ({ id, json: deployJson(id) }));

// Keep the committed catalog when the binary is missing or any app fails, so a
// build without `run` on PATH still ships the last good catalog.
if (results.some((result) => !result.json)) {
  console.warn(
    "[catalog] could not generate every app; keeping committed catalogApps.ts",
  );
  process.exit(0);
}

const apps = results
  .sort((a, b) => a.id.localeCompare(b.id))
  .map(({ id, json }) => {
    const app = json as RunDeployJson;
    return {
      id,
      name: app.displayName ?? app.name,
      description: app.description ?? undefined,
      services: app.services,
      inputs: app.inputs.map((input) => ({
        key: input.key,
        label: input.label ?? undefined,
        required: input.required,
      })),
      hasSecrets: app.hasSecrets,
      hasProxy: app.hasProxy,
      manifest: app.fractalManifest,
    };
  });

const j = (value: unknown) => JSON.stringify(value, null, 2);

const file = `/**
 * Deployable catalog apps, generated from the \`run\` CLI.
 *
 * AUTO-GENERATED by scripts/generateCatalogManifests.ts. Do not edit by hand.
 * Lives under generated/ which biome and knip ignore. Refresh with
 * \`bun run catalog:generate\`.
 */

/** A service in a catalog app's stack, reduced to what the review renders. */
export interface CatalogAppService {
  name: string;
  image: string;
  ports: string[];
}

/** A typed input a catalog app prompts for. */
export interface CatalogAppInput {
  key: string;
  label?: string;
  required: boolean;
}

export interface CatalogApp {
  /** The run catalog id (e.g. "runa"); what \`run up <id>\` takes. */
  id: string;
  name: string;
  description?: string;
  services: CatalogAppService[];
  inputs: CatalogAppInput[];
  /** Whether the stack generates secrets on first run. */
  hasSecrets: boolean;
  /** Whether the stack runs an automatic reverse proxy with HTTPS. */
  hasProxy: boolean;
  /** The Fractal manifest (fractal.yaml) this app deploys. */
  manifest: string;
}

export const catalogApps: CatalogApp[] = ${j(apps)};
`;

await Bun.write(outPath, file);

console.info(`[catalog] Wrote ${apps.length} catalog apps`);
